{
  "core_question": "Should the primary care group accept a full‑risk capitated contract, and what deal structure ensures clinical quality, legal compliance, and financial sustainability?",
  "rationale": "The decision involves evaluating clinical workflow impact, regulatory/legal risk, and economic feasibility, requiring expertise from healthcare operations, health law, and finance.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Given a $1,180 per‑member‑per‑month capitation rate for 25,000 Medicare Advantage members with HEDIS quality bonuses, what clinical operational changes (e.g., staffing, care coordination, EHR workflows) are necessary to meet quality targets and maintain patient safety under full‑risk payment?",
    "legal": "What legal safeguards (contractual clauses, compliance monitoring, anti‑kickback provisions, data privacy, and liability limits) should be included in a Medicare Advantage capitated contract to protect the group from regulatory and litigation risks?",
    "finance": "Using the $1,180 capitation rate for 25,000 members plus projected HEDIS bonuses, what financial model (cost assumptions, risk adjustment, reserve allocation, break‑even analysis) should the group develop to ensure the deal is financially viable under full‑risk payment?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Capitation rates and HEDIS bonus formulas for Medicare Advantage are updated annually; current values may differ from those used in this analysis."
}
